<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101d28"><title>Five Nights, One Saint | A bedtime listening ritual</title>
<style>
:root{--night:#101d28;--deep:#0c1822;--ink:#f4ecd9;--muted:#bac2bc;--gold:#e4bc70;--line:#6e7773;--sea:#91bcb3}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--night);color:var(--ink);font-family:'Trebuchet MS',sans-serif;line-height:1.5;background-image:radial-gradient(ellipse at 84% 8%,#284858 0,transparent 39%),radial-gradient(ellipse at 1% 84%,#243e40 0,transparent 36%)}button,textarea{font:inherit}button{cursor:pointer}a{color:var(--gold)}:focus-visible{outline:3px solid var(--gold);outline-offset:4px}.shell{max-width:1200px;margin:auto;padding:24px clamp(19px,4vw,54px) 80px}.mast{display:flex;justify-content:space-between;align-items:center;gap:20px;font-size:.78rem;letter-spacing:.15em;text-transform:uppercase;color:var(--gold);font-weight:700}.mast a{color:var(--ink);text-decoration:none;border-bottom:1px solid var(--line);padding:5px 0}.hero{position:relative;margin-top:24px;min-height:420px;border:1px solid #556866;border-radius:4px;overflow:hidden;background:#152b32}.hero img{position:absolute;width:100%;height:100%;object-fit:cover;object-position:center 54%;filter:saturate(.83)}.hero:after{content:'';position:absolute;inset:0;background:linear-gradient(270deg,rgba(9,21,30,.97) 0%,rgba(9,21,30,.80) 36%,rgba(9,21,30,.03) 87%),linear-gradient(0deg,rgba(9,21,30,.58),transparent 42%)}.hero-copy{position:relative;z-index:1;padding:clamp(30px,6vw,74px);max-width:620px;margin-left:auto}.eyebrow{font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.25em;color:var(--gold)}h1,h2,h3{font-family:'Palatino Linotype',Georgia,serif;line-height:1.05;font-weight:400}h1{font-size:clamp(3.6rem,8vw,7rem);letter-spacing:-.058em;margin:18px 0 22px}h1 em{font-weight:400;color:var(--gold)}.intro{font-size:clamp(1rem,1.6vw,1.22rem);max-width:480px;color:#e5e5d7}.hero-tag{display:inline-flex;gap:9px;align-items:center;margin-top:14px;padding:10px 13px;background:#0e2732b8;color:#efdfbd;font-size:.75rem;border:1px solid #b89f70}.section-label{color:var(--gold);font-size:.72rem;text-transform:uppercase;letter-spacing:.22em;font-weight:700}.setup{display:grid;grid-template-columns:1fr 1.4fr;gap:clamp(20px,5vw,80px);align-items:end;padding:55px 0 28px;border-bottom:1px solid #59716d}.setup h2{font-size:clamp(2.1rem,4vw,3.4rem);margin:12px 0}.setup p{color:var(--muted);max-width:430px}.saints{display:flex;gap:12px;flex-wrap:wrap}.saint{min-width:210px;flex:1;background:#1e333c;border:1px solid #54716c;color:var(--ink);text-align:left;padding:19px 20px;transition:transform .2s,background .2s,border .2s}.saint:hover{transform:translateY(-3px)}.saint[aria-pressed=true]{background:#3c4a40;border-color:var(--gold);box-shadow:inset 0 0 0 1px var(--gold)}.saint b{display:block;font-family:'Palatino Linotype',Georgia,serif;font-size:1.35rem;font-weight:400}.saint small{color:var(--muted);display:block;margin-top:5px}.timeline{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;padding:32px 0 0}.night{background:#192b33;border:1px solid #566d68;padding:13px 11px 15px;min-height:99px;color:var(--ink);text-align:left;position:relative;transition:background .2s,transform .2s}.night:hover{transform:translateY(-3px)}.night.active{background:#405045;border-color:var(--gold);box-shadow:inset 0 0 0 1px var(--gold)}.night.done:before{content:'✦';position:absolute;right:12px;top:10px;color:var(--gold)}.night span{font-size:.7rem;letter-spacing:.13em;color:var(--gold);text-transform:uppercase}.night strong{display:block;font-family:'Palatino Linotype',Georgia,serif;font-weight:400;font-size:1.15rem;margin-top:10px}.station{display:grid;grid-template-columns:minmax(0,1fr) minmax(270px,.82fr);gap:clamp(20px,4vw,45px);padding-top:28px}.card{background:#e9dfc7;color:#293b3b;padding:clamp(24px,4vw,49px);min-height:385px;position:relative;box-shadow:11px 11px 0 #07151c55}.card:before{content:'';position:absolute;inset:10px;border:1px solid #a1a28a;pointer-events:none}.card>*{position:relative}.card .section-label{color:#84623b}.card h2{font-size:clamp(2.8rem,5vw,4.7rem);letter-spacing:-.04em;margin:14px 0 17px}.card .prompt{font-family:'Palatino Linotype',Georgia,serif;font-size:clamp(1.35rem,2vw,1.8rem);line-height:1.35;max-width:480px}.card .hint{color:#546464;font-size:.89rem}.ritual{padding:25px 0}.ritual h3{font-size:2rem;margin:10px 0 12px}.ritual p{color:var(--muted);max-width:400px}.ritual label{display:block;color:var(--gold);font-size:.73rem;letter-spacing:.15em;text-transform:uppercase;font-weight:700;margin:27px 0 10px}.ritual textarea{resize:vertical;min-height:90px;background:#10242e;color:var(--ink);border:1px solid #70837a;width:100%;padding:13px 15px;border-radius:0}.ritual textarea::placeholder{color:#9facaa}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:15px}.primary,.secondary{border:1px solid var(--gold);padding:12px 17px;min-height:48px;font-size:.81rem;letter-spacing:.05em;font-weight:700}.primary{background:var(--gold);color:#16262d}.primary:hover{background:#f4d49b}.secondary{background:transparent;color:var(--ink)}.secondary:hover{background:#30443e}.footer{display:flex;justify-content:space-between;gap:25px;align-items:end;border-top:1px solid #56706d;margin-top:58px;padding-top:27px;color:var(--muted);font-size:.88rem}.footer p{max-width:520px;margin:0}.footer a{color:var(--gold)}.tiny{font-size:.76rem}.sr-only{position:absolute;clip:rect(0,0,0,0);white-space:nowrap;width:1px;height:1px;overflow:hidden}.fade{animation:rise .4s ease both}@keyframes rise{from{opacity:.3;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}@media(max-width:760px){.hero{min-height:420px}.hero:after{background:linear-gradient(0deg,#0a1b26f7 5%,#0a1b2670 85%)}.hero img{object-position:61% center}.hero-copy{padding:28px;position:absolute;bottom:0;margin-left:0}.setup,.station{grid-template-columns:1fr}.setup{padding-top:39px}.timeline{gap:5px}.night{min-height:88px;padding:9px 5px}.night strong{font-size:.89rem}.night span{font-size:.57rem}.night.done:before{right:5px;top:3px}.card{min-height:320px}.footer{display:block}.footer p+p{margin-top:20px}}@media(max-width:420px){.timeline{grid-template-columns:repeat(5,minmax(0,1fr))}.night strong{font-size:.78rem;overflow-wrap:anywhere}.saint{min-width:100%}h1{font-size:3.3rem}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
</style></head><body><div class="shell"><header class="mast"><span>✦ The bedtime field guide</span><a href="index.php">← All curiosities</a></header><main><section class="hero"><img src="five-nights-lantern.png" alt="A warm brass lantern beside a tropical shore beneath five stars" fetchpriority="high"><div class="hero-copy"><span class="eyebrow">An episode. A question. A little light.</span><h1>Five nights,<br><em>one saint.</em></h1><p class="intro">A tiny listening companion for a parent and child. Put on an episode, talk for a minute, and mark a star together.</p><div class="hero-tag">✦ Your notes stay in this browser</div></div></section><section class="setup" aria-labelledby="choose-title"><div><span class="section-label">01 / Choose a journey</span><h2 id="choose-title">Whose story tonight?</h2><p>Inspired by the two saints Jon mentioned enjoying with Nathan. This doesn't play the podcast; it's a companion for listening together.</p></div><div class="saints" role="group" aria-label="Choose a saint"><button type="button" class="saint" data-saint="damien" aria-pressed="true"><b>St. Damien</b><small>Molokai · courage &amp; companionship</small></button><button type="button" class="saint" data-saint="louis" aria-pressed="false"><b>St. Louis IX</b><small>France · leadership &amp; kindness</small></button></div></section><div class="timeline" role="group" aria-label="Choose a listening night"></div><section class="station" aria-label="Tonight's listening card"><article class="card" id="story-card" aria-live="polite"></article><aside class="ritual"><span class="section-label">02 / After the episode</span><h3>Keep one bright thing.</h3><p>Ask the question on the card. A single sentence is plenty; a long conversation is lovely too.</p><label for="memory">Our one-line memory</label><textarea id="memory" maxlength="500" placeholder="Tonight we noticed…"></textarea><div class="actions"><button class="primary" type="button" id="mark">✦ Mark this night</button><button class="secondary" type="button" id="clear">Start this saint over</button></div><p class="tiny" id="status" role="status">Five nights, one story at a time.</p></aside></section></main><footer class="footer"><p>Inspired by Jon's <a href="https://cooltoolsforcatholics.blogspot.com/2025/12/the-saints-podcast.html" target="_blank" rel="noopener noreferrer">The Saints Podcast</a>, and the ritual of listening with Nathan before bed. Listen to the real episodes on the podcast, then return here for your little conversation.</p><p class="tiny">Made for a quiet minute together · No account, no upload</p></footer></div>
<script>
(()=>{'use strict';const names=['The beginning','The choice','The hard part','A helping hand','Carry it home'];const prompts={damien:[['Before you listen','When someone feels left out, what could help them feel less alone?'],['A brave choice','What is one small brave thing a person can do for someone else?'],['When it gets difficult','How can we keep showing up for a friend when helping is hard?'],['People around us','Who has helped you feel welcome, and how did they do it?'],['Bring it home','What is one kind thing we could do together tomorrow?']],louis:[['Before you listen','What do you think makes someone a good leader?'],['A brave choice','Would you rather be powerful or fair? Why?'],['When it gets difficult','How do you know what is right when two people disagree?'],['People around us','Who helps you make a good choice when you feel unsure?'],['Bring it home','Where can we practice kindness in our own little kingdom tomorrow?']]};const key='five-nights-one-saint-v1';let saved;try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{saved={}};let saint=['damien','louis'].includes(saved.saint)?saved.saint:'damien',night=Math.max(0,Math.min(4,Number(saved.night)||0));const records=(saved.records&&typeof saved.records==='object')?saved.records:{};const line=(s,n)=>s+':'+n;const timeline=document.querySelector('.timeline'),card=document.getElementById('story-card'),memo=document.getElementById('memory'),mark=document.getElementById('mark'),status=document.getElementById('status');function store(){try{localStorage.setItem(key,JSON.stringify({saint,night,records}))}catch{status.textContent='Browser storage is unavailable; notes will last only until you leave.'}}function saveMemo(){const id=line(saint,night);records[id]={...(records[id]||{}),text:memo.value.slice(0,500)};store()}function render(){document.querySelectorAll('.saint').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.saint===saint)));timeline.replaceChildren();names.forEach((name,i)=>{const b=document.createElement('button');b.type='button';b.className='night'+(night===i?' active':'')+(records[line(saint,i)]?.done?' done':'');b.setAttribute('aria-label','Night '+(i+1)+': '+name+(records[line(saint,i)]?.done?', completed':''));b.setAttribute('aria-pressed',String(night===i));b.innerHTML='<span>Night '+(i+1)+'</span><strong>'+name+'</strong>';b.addEventListener('click',()=>{saveMemo();night=i;store();render()});timeline.append(b)});const [theme,question]=prompts[saint][night];card.classList.remove('fade');void card.offsetWidth;card.classList.add('fade');card.innerHTML='<span class="section-label">Night '+(night+1)+' of 5 · '+(saint==='damien'?'St. Damien':'St. Louis IX')+'</span><h2>'+names[night]+'.</h2><p class="prompt">“'+question+'”</p><p class="hint">'+theme+' · Try asking after the episode, or use the question before you press play.</p>';memo.value=records[line(saint,night)]?.text||'';const done=!!records[line(saint,night)]?.done;mark.textContent=done?'✦ Night marked — tap to undo':'✦ Mark this night';const count=names.filter((_,i)=>records[line(saint,i)]?.done).length;status.textContent=count===5?'All five stars are shining. Start a new story whenever you like.':count+' of 5 nights marked for '+(saint==='damien'?'St. Damien':'St. Louis IX')+'.'}memo.addEventListener('input',saveMemo);document.querySelectorAll('.saint').forEach(b=>b.addEventListener('click',()=>{saveMemo();saint=b.dataset.saint;night=0;store();render()}));mark.addEventListener('click',()=>{saveMemo();const id=line(saint,night);records[id].done=!records[id].done;store();render()});document.getElementById('clear').addEventListener('click',()=>{if(!confirm('Clear all five nights and notes for this saint?'))return;names.forEach((_,i)=>delete records[line(saint,i)]);night=0;store();render()});render()})();
</script></body></html>